class BankAccount { private String accountNo,accountHolderName; private double balance; BankAccount(String accountNo,String accountHolderName,double balance){this.accountNo=accountNo;this.accountHolderName=accountHolderName;this.balance=balance;} void deposit(double amount){if(amount>0)balance+=amount;} void withdraw(double amount){boolean success=amount>0&&amount<=balance;if(success)balance-=amount;System.out.println(success?"Withdrawal successful":"Withdrawal failed");} double getBalance(){return balance;} void displayAccount(){System.out.println(accountNo+" "+accountHolderName+" "+balance);} }
public class Q08_BankAccountMain { public static void main(String[] a){BankAccount b=new BankAccount("A1","Ravi",1000);b.deposit(200);b.withdraw(500);b.withdraw(1000);b.displayAccount();} }
